function h(a){const t=1/(1+.3275911*Math.abs(a)/Math.SQRT2),n=1-((((1.061405429*t-1.453152027)*t+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-(a*a)/2);return a>=0?(1+n)/2:(1-n)/2}function u(a,t,n,o,r){if(n<=0)return Math.max(a-t,0);const e=(Math.log(a/t)+(o+r*r/2)*n)/(r*Math.sqrt(n)),s=e-r*Math.sqrt(n);return a*h(e)-t*Math.exp(-o*n)*h(s)}function M(a,t,n,o,r){return u(a,t,n,o,r)-a+t*Math.exp(-o*n)}function c(a,t,n,o,r){if(n<=0)return a>t?1:0;const e=(Math.log(a/t)+(o+r*r/2)*n)/(r*Math.sqrt(n));return h(e)}export{c as a,u as b,M as c,h as n};
